{
  "4": {
    "class_type": "SaveImageAdvanced",
    "inputs": {
      "filename_prefix": "ComfyUI",
      "format": "png",
      "format.bit_depth": "8-bit",
      "format.input_color_space": "sRGB",
      "images": [
        "9:3",
        0
      ]
    },
    "_meta": {
      "title": "保存图像（高级）"
    }
  },
  "9:1": {
    "class_type": "CheckpointLoaderSimple",
    "inputs": {
      "ckpt_name": "%model%"
    },
    "_meta": {
      "title": "Checkpoint加载器（简易）"
    }
  },
  "9:2": {
    "class_type": "KSampler",
    "inputs": {
      "seed": "%seed%",
      "steps": "%steps%",
      "cfg": "%cfg%",
      "sampler_name": "euler",
      "scheduler": "simple",
      "denoise": 1,
      "model": [
        "9:1",
        0
      ],
      "positive": [
        "9:5",
        0
      ],
      "negative": [
        "9:6",
        0
      ],
      "latent_image": [
        "9:8",
        0
      ]
    },
    "_meta": {
      "title": "K采样器"
    }
  },
  "9:3": {
    "class_type": "VAEDecode",
    "inputs": {
      "samples": [
        "9:2",
        0
      ],
      "vae": [
        "9:7",
        0
      ]
    },
    "_meta": {
      "title": "VAE解码"
    }
  },
  "9:5": {
    "class_type": "CLIPTextEncode",
    "inputs": {
      "text": "masterpiece, best quality, amazing quality, very awa,absurdres,newest,very aesthetic,depth of field,highres,%text%",
      "clip": [
        "9:1",
        1
      ]
    },
    "_meta": {
      "title": "CLIP文本编码"
    }
  },
  "9:6": {
    "class_type": "CLIPTextEncode",
    "inputs": {
      "text": "%negative_prompt%",
      "clip": [
        "9:1",
        1
      ]
    },
    "_meta": {
      "title": "CLIP文本编码"
    }
  },
  "9:7": {
    "class_type": "VAELoader",
    "inputs": {
      "vae_name": "sdxl_vae.safetensors"
    },
    "_meta": {
      "title": "加载VAE"
    }
  },
  "9:8": {
    "class_type": "EmptyLatentImage",
    "inputs": {
      "width": "%width%",
      "height": "%height%",
      "batch_size": "%batch_size%"
    },
    "_meta": {
      "title": "空Latent图像"
    }
  }
}
